 964→// ── Send message history to a single browser socket ────────────────────────
 965→
 966→/** Send initial state (workspaces, agent list, tasks) to a newly connected browser. */
 967→function sendFullStateToSocket(ws: WebSocket) {
 968→  if (ws.readyState !== WebSocket.OPEN) return;
 969→
 970→  // Workspace list
 971→  ws.send(JSON.stringify({ type: "workspace_list", workspaces: Array.from(workspaces.values()) }));
 972→
 973→  // Agent list (sidebar metadata) — scoped if browser has a workspace set
 974→  const scope = browserWorkspaceScope.get(ws) ?? null;
 975→  ws.send(JSON.stringify({ type: "agent_list", agents: buildAgentList(scope) }));
 976→
 977→  // Task list — scoped if browser has a workspace set
 978→  ws.send(JSON.stringify({ type: "task_list", tasks: buildTaskList(scope) }));
 979→}
 980→
 981→/** Send message history for a single agent to a specific browser socket. */
 982→function sendHistoryToSocket(ws: WebSocket, agentId: string) {
 983→  const agent = agents.get(agentId);
 984→  if (!agent || ws.readyState !== WebSocket.OPEN) return;
 985→  ws.send(
 986→    JSON.stringify({
 987→      type: "message_history",
 988→      agentId: agent.agentId,
 989→      messages: agent.messageHistory,
 990→    })
 991→  );
 992→}
 993→
 994→// ── Connection handler — route by URL path ────────────────────────────────
 995→wss.on("connection", (ws: WebSocket, req: IncomingMessage) => {
 996→  const path = req.url ?? "/";
 997→  console.log(`[ws connected] path=${path}`);
 998→
 999→  if (path === "/browser") {
1000→    // Send full state BEFORE adding to browserSockets so that live
1001→    // relay broadcasts don't interleave with the history replay.
1002→    sendFullStateToSocket(ws);
1003→    browserSockets.add(ws);
1004→
1005→    ws.on("message", (data) => {
1006→      handleBrowserMessage(data.toString(), ws);
1007→    });
1008→
1009→    ws.on("close", () => {
1010→      console.log("[browser disconnected]");
1011→      browserSockets.delete(ws);
1012→      browserWorkspaceScope.delete(ws);
1013→      // Do NOT kill agents — keep them alive for reconnect
1014→    });
1015→  } else if (path.startsWith("/claude/")) {
1016→    // Parse agentId from /claude/<agentId>
1017→    const agentId = path.slice("/claude/".length);
1018→    const agent = agents.get(agentId);
1019→
1020→    if (!agent) {
1021→      console.log(`[ws] unknown agentId: ${agentId}, closing`);
1022→      ws.close();
1023→      return;
1024→    }
1025→
1026→    agent.claudeSocket = ws;
1027→    console.log(`[claude:${agentId} CLI connected via WebSocket]`);
1028→
1029→    // Notify browsers that CLI is connected
1030→    sendToBrowser({ type: "cli_connected", agentId });
1031→
1032→    // Flush any pending messages queued while CLI was disconnected
1033→    if (agent.pendingMessages.length > 0) {
1034→      console.log(`[flush] sending ${agent.pendingMessages.length} queued messages to agent ${agentId}`);
1035→      for (const queued of agent.pendingMessages) {
1036→        ws.send(queued + "\n");
1037→      }
1038→      agent.pendingMessages = [];
1039→      persistAgentSync(agent);
1040→    }
1041→
1042→    // Send the pending prompt immediately — CLI 2.1.42+ waits for the
1043→    // server to send the first user message rather than emitting
1044→    // hook_started/hook_response on connect.
1045→    if (agent.pendingPrompt && ws.readyState === WebSocket.OPEN) {
1046→      const promptContent = agent.pendingPrompt;
1047→      const userMsg = JSON.stringify({
1048→        type: "user",
1049→        message: { role: "user", content: promptContent },
1050→        parent_tool_use_id: null,
1051→        session_id: agent.sessionId ?? "",
1052→      });
1053→      console.log(`[server → claude:${agentId}] sending pending prompt`);
1054→      ws.send(userMsg + "\n");
1055→      agent.pendingPrompt = null;
1056→      setAgentStatus(agentId, "thinking");
1057→
1058→      // Record the initial user message so it appears in chat and persists across reloads
1059→      recordAndSend(agentId, {
1060→        type: "relay",
1061→        agentId,
1062→        message: { type: "user", message: { role: "user", content: promptContent } } as ClaudeMessage,
1063→      });
1064→    }
1065→
1066→    ws.on("message", (data) => {
1067→      handleClaudeMessage(agentId, data.toString());
1068→    });
1069→
1070→    ws.on("close", () => {
1071→      console.log(`[claude:${agentId} CLI disconnected]`);
1072→      if (agent.claudeSocket === ws) {
1073→        agent.claudeSocket = null;
1074→        if (agent.status !== "error") {
1075→          setAgentStatus(agentId, "done");
1076→          sendToBrowser({ type: "cli_disconnected", agentId });
1077→
1078→          // Auto-complete any task linked to this agent
1079→          for (const task of tasks.values()) {
1080→            if (task.agentId === agentId && task.status !== "done") {
1081→              task.status = "done";
1082→              task.updatedAt = Date.now();
1083→              persistTasks();
1084→              broadcastTaskList();
1085→              break;
1086→            }
1087→          }
1088→        }
1089→      }
1090→    });
1091→  } else {
1092→    console.log(`[ws] unknown path: ${path}, closing`);
1093→    ws.close();
1094→  }
1095→});
