 49→  ClaudeAssistant,
 50→  ClaudeControlRequest,
 51→  ClaudeMessage,
 52→  ClaudeResult,
 53→  ClaudeSystemInit,
 54→  DirectoryEntry,
 55→  NotificationItem,
 56→  NotificationType,
 57→  ServerMessage,
 58→  ServerMessageHistory,
 59→  ServerTaskList,
 60→  ServerTaskUpdated,
 61→  ServerTaskDeleted,
 62→  Task,
 63→  TaskPriority,
 64→  ToolCallInfo,
 65→  UserQuestion,
 66→  Workspace,
 67→} from "@/lib/types";
