 76→/** Connect to the WS server on the same host the page was loaded from. */
 77→const WS_URL =
 78→  typeof window !== "undefined"
 79→    ? `ws://${window.location.hostname}:9900/browser`
 80→    : "ws://localhost:9900/browser";
