 82→/** Per-agent client state. */
 83→export interface AgentClientState {
 84→  status: AgentStatus;
 85→  messages: ChatMessage[];
 86→  /** Raw Claude NDJSON messages for debug view. */
 87→  rawMessages: ClaudeMessage[];
 88→  label: string;
