916→  // Derived values for the active agent
917→  const activeAgent = activeAgentId ? agents.get(activeAgentId) : undefined;
918→  const activeStatus = useMemo<AgentStatus>(
919→    () => activeAgent?.status ?? "idle",
920→    [activeAgent?.status]
921→  );
