151→
152→  const handleMenuButton = useCallback((e: React.MouseEvent, agentId: string) => {
153→    e.stopPropagation();
154→    const rect = (e.currentTarget as HTMLElement).getBoundingClientRect();
155→    openMenu(agentId, rect.right, rect.bottom);
156→  }, [openMenu]);
157→
158→  const closeMenu = useCallback(() => setCtxMenu(null), []);
159→
160→  function renderAgentRow(id: string, dimmed: boolean) {
161→    const agent = agents.get(id);
162→    if (!agent) return null;
163→    const isActive = id === activeAgentId;
164→    return (
165→      <div
166→        key={id}
167→        onClick={() => onSelect(id)}
168→        onContextMenu={(e) => handleContextMenu(e, id)}
169→        className={cn(
170→          "group flex w-full cursor-pointer items-start gap-0.5 px-3 py-2 text-left text-xs transition-colors",
171→          isActive ? "bg-sidebar-accent" : "hover:bg-sidebar-accent/50",
172→          dimmed && "opacity-60"
173→        )}
174→      >
175→        <div className="flex min-w-0 flex-1 flex-col gap-0.5">
176→          <span className="flex items-center gap-2">
177→            <span className={cn("inline-block size-2 shrink-0 rounded-full", STATUS_DOT[agent.status])} />
178→            {renamingId === id ? (
179→              <RenameInput
180→                initialValue={agent.label}
181→                onConfirm={(label) => {
182→                  onRename(id, label);
183→                  setRenamingId(null);
184→                }}
185→                onCancel={() => setRenamingId(null)}
186→              />
187→            ) : (
188→              <Tip text={agent.label || "new agent"} side="right"><span className="truncate">{agent.label || "new agent"}</span></Tip>
189→            )}
190→            {agent.pinned && (
191→              <Pin className="size-2.5 shrink-0 text-muted-foreground" />
192→            )}
193→            {agent.iceboxed && (
194→              <Snowflake className="size-2.5 shrink-0 text-muted-foreground" />
195→            )}
196→          </span>
197→          <span className="pl-4 text-[10px] text-muted-foreground truncate font-mono">
198→            {id}
199→            {(() => {
200→              const ws = workspaces.find((w) => w.id === agent.workspaceId);
201→              return ws ? <span className="opacity-60"> · {ws.name}</span> : null;
202→            })()}
203→          </span>
204→        </div>
205→        <button
206→          onClick={(e) => handleMenuButton(e, id)}
207→          className="shrink-0 rounded p-0.5 opacity-0 transition-opacity hover:bg-sidebar-accent group-hover:opacity-100"
208→          aria-label="Agent menu"
209→        >
210→          <EllipsisVertical className="size-3.5 text-muted-foreground" />
211→        </button>
212→      </div>
213→    );
214→  }
215→
216→  return (
217→    <div className="flex h-full w-56 flex-col border-r bg-sidebar text-sidebar-foreground">
218→      {/* Workspace switcher */}
219→      <div className="border-b">
220→        <WorkspaceSwitcher
221→          workspaces={workspaces}
222→          activeWorkspaceId={activeWorkspaceId}
223→          onSelect={onSelectWorkspace}
224→          onRename={onRenameWorkspace}
225→          onDelete={onDeleteWorkspace}
226→          onOpenFolder={onOpenFolder}
227→        />
228→      </div>
229→
230→      {/* Header */}
231→      <div className="flex items-center justify-between px-3 py-2">
232→        <span className="text-xs font-semibold">agents</span>
233→        <button
234→          onClick={onNewAgent}
235→          className="rounded-md p-1 hover:bg-sidebar-accent transition-colors"
236→          aria-label="New agent"
237→        >
238→          <Plus className="size-3.5" />
239→        </button>
240→      </div>
241→
242→      {/* Agent list */}
243→      <div className="flex-1 overflow-y-auto">
244→        {loading ? (
245→          <div className="space-y-1 px-3 py-2">
246→            {[...Array(4)].map((_, i) => (
247→              <div key={i} className="flex items-center gap-2 py-2">
248→                <div className="size-2 rounded-full bg-muted-foreground/20 animate-pulse" />
249→                <div className="h-3 flex-1 rounded bg-muted-foreground/20 animate-pulse" style={{ width: `${60 + i * 10}%` }} />
250→              </div>
251→            ))}
252→          </div>
253→        ) : agentOrder.length === 0 ? (
254→          <div className="px-3 py-4 text-xs text-muted-foreground">
255→            No agents yet
256→          </div>
257→        ) : null}
258→
259→        {/* Pinned agents */}
260→        {pinnedIds.length > 0 && (
261→          <>
262→            <div className="flex items-center gap-2 px-3 pt-2 pb-1">
263→              <span className="text-[10px] font-medium text-muted-foreground uppercase tracking-wider">pinned</span>
264→              <div className="flex-1 border-t" />
265→            </div>
266→            {pinnedIds.map((id) => renderAgentRow(id, false))}
267→          </>
268→        )}
269→
270→        {/* Active agents */}
271→        {activeIds.length > 0 && (
272→          <>
273→            {pinnedIds.length > 0 && (
274→              <div className="flex items-center gap-2 px-3 pt-3 pb-1">
275→                <span className="text-[10px] font-medium text-muted-foreground uppercase tracking-wider">active</span>
276→                <div className="flex-1 border-t" />
277→              </div>
278→            )}
279→            {activeIds.map((id) => renderAgentRow(id, false))}
280→          </>
281→        )}
282→
283→        {/* Icebox agents */}
284→        {iceboxIds.length > 0 && (
285→          <>
286→            <div className="flex items-center gap-2 px-3 pt-3 pb-1">
287→              <span className="text-[10px] font-medium text-muted-foreground uppercase tracking-wider">icebox</span>
288→              <div className="flex-1 border-t" />
289→            </div>
290→            {iceboxIds.map((id) => renderAgentRow(id, true))}
291→          </>
292→        )}
293→
294→        {/* Archived divider + agents */}
295→        {archivedIds.length > 0 && (
296→          <>
297→            <div className="flex items-center gap-2 px-3 pt-3 pb-1">
298→              <span className="text-[10px] font-medium text-muted-foreground uppercase tracking-wider">archived</span>
299→              <div className="flex-1 border-t" />
300→            </div>
301→            {archivedIds.map((id) => renderAgentRow(id, true))}
302→          </>
303→        )}
304→      </div>
305→
306→      {/* Context menu — portaled to body to escape sidebar stacking context */}
307→      {ctxMenu && (() => {
308→        const agent = agents.get(ctxMenu.agentId);
309→        if (!agent) return null;
310→        return createPortal(
311→          <div
312→            ref={menuRef}
