 27→
 28→export const COMMANDS: SlashCommand[] = [
 29→  { name: "commit", description: "Create a git commit", icon: GitCommit },
 30→  { name: "review-pr", description: "Review a pull request", icon: GitPullRequest },
 31→  { name: "clear", description: "Clear conversation history", icon: Trash2, clientSide: true },
 32→  { name: "compact", description: "Compact conversation context", icon: Minimize2 },
 33→  { name: "cost", description: "Show token usage and costs", icon: DollarSign },
 34→  { name: "doctor", description: "Check environment health", icon: Stethoscope },
 35→  { name: "init", description: "Initialize CLAUDE.md", icon: FileText },
 36→  { name: "config", description: "Open configuration", icon: Settings },
 37→  { name: "memory", description: "Edit memory files", icon: Brain },
 38→  { name: "status", description: "Show agent status", icon: Activity },
 39→  { name: "context", description: "Show session context usage", icon: FolderOpen, clientSide: true },
 40→  { name: "model", description: "Change model", icon: Cpu },
 41→  { name: "help", description: "Show available commands", icon: HelpCircle },
 42→];
 43→
 44→export function filterCommands(query: string): SlashCommand[] {
 45→  if (!query) return COMMANDS;
 46→  const q = query.toLowerCase();
 47→  return COMMANDS.filter((cmd) => cmd.name.toLowerCase().includes(q));
 48→}
 49→
 50→export function SlashCommandMenu({
 51→  query,
 52→  highlightedIndex,
 53→  onSelect,
 54→  onHighlight,
 55→}: {
 56→  query: string;
 57→  highlightedIndex: number;
 58→  onSelect: (command: SlashCommand) => void;
 59→  onHighlight: (index: number) => void;
 60→}) {
 61→  const filtered = filterCommands(query);
 62→
 63→  if (filtered.length === 0) {
 64→    return (
 65→      <div className="absolute bottom-full left-0 right-0 mb-1 rounded-lg border bg-popover p-3 shadow-lg">
 66→        <span className="text-sm text-muted-foreground">No matching commands</span>
 67→      </div>
 68→    );
 69→  }
 70→
 71→  return (
 72→    <div className="absolute bottom-full left-0 right-0 mb-1 max-h-64 overflow-y-auto rounded-lg border bg-popover shadow-lg">
 73→      {filtered.map((cmd, i) => {
 74→        const Icon = cmd.icon;
 75→        return (
 76→          <button
 77→            key={cmd.name}
 78→            type="button"
 79→            className={cn(
 80→              "flex w-full items-center gap-3 px-3 py-2.5 text-sm text-left transition-colors",
 81→              i === highlightedIndex
