 84→            )}
 85→            onMouseEnter={() => onHighlight(i)}
 86→            onMouseDown={(e) => {
 87→              e.preventDefault(); // prevent input blur
 88→              onSelect(cmd);
 89→            }}
 90→          >
 91→            <Icon className="size-4 shrink-0 text-muted-foreground" />
 92→            <div className="min-w-0 flex-1">
 93→              <span className="font-medium">/{cmd.name}</span>
 94→              <span className="ml-2 text-muted-foreground">{cmd.description}</span>
 95→            </div>
 96→          </button>
 97→        );
 98→      })}
 99→    </div>
100→  );
101→}
