  3→/**
  4→ * Main chat interface for the thos dashboard.
  5→ *
  6→ * Composes {@link StatusBar}, a scrollable message list ({@link Message}
  7→ * and {@link ControlRequest} cards), and an input bar. The submit button
  8→ * text toggles between "Spawn" (when idle/done) and "Send" (when an
  9→ * agent session is active). Auto-scrolls on new messages.
 10→ *
 11→ * A toggle in the top-right switches between the processed chat view
 12→ * and a raw JSON view of all Claude NDJSON messages.
 13→ *
 14→ * Receives all data and callbacks via props — the parent page component
 15→ * owns the WebSocket hook and orchestrates multiple agents.
 16→ */
 17→
 18→import { useMemo, useRef, useState } from "react";
 19→import { Virtuoso, type VirtuosoHandle } from "react-virtuoso";
 20→import { ArrowDown, ListTodo, MessageSquare, Terminal } from "lucide-react";
 21→import type { AgentStatus, ChatMessage, ClaudeMessage, NotificationItem } from "@/lib/types";
 22→import { condenseMessages } from "@/lib/condense-messages";
 23→import { StatusBar } from "./status-bar";
 24→import { AgentSummary } from "./agent-summary";
 25→import { Message } from "./message";
 26→import { ControlRequest } from "./control-request";
 27→import { UserQuestion } from "./user-question";
 28→import { CondensedToolGroup } from "./condensed-tool-group";
 29→import { SlashCommandMenu, filterCommands, type SlashCommand } from "./slash-command-menu";
 30→import { ContextUsageCard } from "./context-usage-card";
 31→import { Button } from "@/components/ui/button";
 32→
 33→export function Chat({
 34→  connected,
 35→  loading,
 36→  status,
 37→  agentLabel,
 38→  messages,
 39→  rawMessages,
 40→  activeModel,
 41→  selectedModel,
 42→  onModelChange,
 43→  onSendMessage,
 44→  onSpawnAgent,
 45→  onRespondToControl,
 46→  onRespondToUserQuestion,
 47→  onClearHistory,
 48→  showTasks,
 49→  onToggleTasks,
 50→  showDiffs,
 51→  onToggleDiffs,
 52→  onToggleSidebar,
 53→  onOpenSfxSettings,
 54→  notificationsEnabled,
 55→  onToggleNotifications,
 56→  notifications,
 57→  onSelectNotification,
 58→  onDismissNotification,
 59→  onClearNotifications,
 60→}: {
 61→  connected: boolean;
 62→  loading?: boolean;
 63→  status: AgentStatus;
 64→  agentLabel?: string | null;
 65→  messages: ChatMessage[];
 66→  rawMessages: ClaudeMessage[];
 67→  activeModel?: string | null;
 68→  selectedModel?: string;
 69→  onModelChange?: (model: string) => void;
 70→  onSendMessage: (content: string) => void;
 71→  onSpawnAgent: (prompt: string) => void;
 72→  onRespondToControl: (requestId: string, allow: boolean) => void;
 73→  onRespondToUserQuestion: (requestId: string, answers: Record<string, string>) => void;
 74→  onClearHistory?: () => void;
 75→  showTasks?: boolean;
 76→  onToggleTasks?: () => void;
 77→  showDiffs?: boolean;
 78→  onToggleDiffs?: () => void;
 79→  onToggleSidebar?: () => void;
 80→  onOpenSfxSettings?: () => void;
 81→  notificationsEnabled?: boolean;
 82→  onToggleNotifications?: () => void;
 83→  notifications?: NotificationItem[];
 84→  onSelectNotification?: (agentId: string, notificationId: string) => void;
 85→  onDismissNotification?: (id: string) => void;
 86→  onClearNotifications?: () => void;
 87→}) {
 88→  const [input, setInput] = useState("");
 89→  const [showRaw, setShowRaw] = useState(false);
 90→  const [showContext, setShowContext] = useState(false);
 91→  const [showSlashMenu, setShowSlashMenu] = useState(false);
 92→  const [slashQuery, setSlashQuery] = useState("");
 93→  const [slashHighlight, setSlashHighlight] = useState(0);
 94→  const [atBottom, setAtBottom] = useState(true);
 95→  const virtuosoRef = useRef<VirtuosoHandle>(null);
 96→  const inputRef = useRef<HTMLInputElement>(null);
 97→
 98→  const displayItems = useMemo(() => condenseMessages(messages), [messages]);
 99→  const isActive = status === "connected" || status === "thinking";
100→  const isArchived = status === "done" || status === "disconnected" || status === "error";
101→
102→  function handleSubmit(e: React.FormEvent) {
103→    e.preventDefault();
104→    const trimmed = input.trim();
105→    if (!trimmed) return;
106→
107→    if (isActive) {
108→      onSendMessage(trimmed);
109→    } else {
110→      onSpawnAgent(trimmed);
111→    }
112→    setInput("");
113→    setShowSlashMenu(false);
114→  }
115→
116→  function handleInputChange(e: React.ChangeEvent<HTMLInputElement>) {
117→    const value = e.target.value;
118→    setInput(value);
119→
120→    if (value.startsWith("/")) {
121→      setShowSlashMenu(true);
122→      setSlashQuery(value.slice(1));
123→      setSlashHighlight(0);
124→    } else {
125→      setShowSlashMenu(false);
126→      setSlashQuery("");
127→    }
128→  }
129→
130→  function handleKeyDown(e: React.KeyboardEvent<HTMLInputElement>) {
131→    if (!showSlashMenu) return;
132→    const filtered = filterCommands(slashQuery);
133→    if (filtered.length === 0) return;
134→
135→    if (e.key === "ArrowDown") {
136→      e.preventDefault();
137→      setSlashHighlight((i) => (i + 1) % filtered.length);
138→    } else if (e.key === "ArrowUp") {
139→      e.preventDefault();
140→      setSlashHighlight((i) => (i - 1 + filtered.length) % filtered.length);
141→    } else if (e.key === "Enter") {
142→      e.preventDefault();
143→      handleCommandSelect(filtered[slashHighlight]);
144→    } else if (e.key === "Escape") {
145→      e.preventDefault();
146→      setShowSlashMenu(false);
147→    } else if (e.key === "Tab") {
148→      e.preventDefault();
149→      setInput(`/${filtered[slashHighlight].name} `);
150→      setShowSlashMenu(false);
151→    }
152→  }
153→
154→  function handleCommandSelect(command: SlashCommand) {
155→    setShowSlashMenu(false);
156→    setSlashQuery("");
157→    setInput("");
158→
159→    if (command.clientSide) {
160→      if (command.name === "clear") {
161→        onClearHistory?.();
162→      } else if (command.name === "context") {
163→        setShowContext((v) => !v);
164→      }
165→      return;
166→    }
167→
168→    const commandText = `/${command.name}`;
169→    if (isActive) {
170→      onSendMessage(commandText);
171→    } else {
172→      onSpawnAgent(commandText);
173→    }
174→  }
175→
176→  return (
177→    <div className="flex h-full flex-col">
178→      <StatusBar
179→        connected={connected}
180→        status={status}
181→        agentLabel={agentLabel}
182→        activeModel={activeModel}
183→        selectedModel={selectedModel}
184→        onModelChange={onModelChange}
185→        showRaw={showRaw}
186→        onToggleRaw={() => setShowRaw((v) => !v)}
187→        showTasks={showTasks}
188→        onToggleTasks={onToggleTasks}
189→        showDiffs={showDiffs}
190→        onToggleDiffs={onToggleDiffs}
191→        onToggleSidebar={onToggleSidebar}
192→        onOpenSfxSettings={onOpenSfxSettings}
193→        notificationsEnabled={notificationsEnabled}
194→        onToggleNotifications={onToggleNotifications}
195→        notifications={notifications}
196→        onSelectNotification={onSelectNotification}
197→        onDismissNotification={onDismissNotification}
198→        onClearNotifications={onClearNotifications}
199→      />
200→
201→      <AgentSummary rawMessages={rawMessages} />
202→
203→      <div className="relative flex-1">
204→        {loading ? (
205→          <div className="flex h-full flex-col items-center justify-center gap-3">
206→            <div className="flex gap-1">
207→              <div className="size-2 rounded-full bg-muted-foreground/40 animate-pulse" />
208→              <div className="size-2 rounded-full bg-muted-foreground/40 animate-pulse [animation-delay:150ms]" />
209→              <div className="size-2 rounded-full bg-muted-foreground/40 animate-pulse [animation-delay:300ms]" />
210→            </div>
211→            <span className="text-xs text-muted-foreground">
212→              {connected ? "Loading messages..." : "Connecting..."}
213→            </span>
214→          </div>
215→        ) : showRaw ? (
216→          <div className="h-full overflow-y-auto p-2 md:p-4 space-y-1">
217→            {rawMessages.length === 0 ? (
218→              <div className="flex h-full items-center justify-center text-sm text-muted-foreground">
219→                No raw messages yet
220→              </div>
221→            ) : (
222→              rawMessages.map((msg, i) => (
223→                <RawMessage key={i} message={msg} index={i} />
224→              ))
225→            )}
226→          </div>
227→        ) : (
228→          <Virtuoso
229→            ref={virtuosoRef}
230→            data={displayItems}
231→            style={{ height: "100%" }}
232→            initialTopMostItemIndex={displayItems.length - 1}
233→            followOutput={(isAtBottom) => isAtBottom ? "smooth" : false}
234→            atBottomStateChange={setAtBottom}
235→            increaseViewportBy={200}
236→            itemContent={(_index, item) => (
237→              <div className="px-2 pb-2 md:px-4">
238→                {item.kind === "condensed" ? (
239→                  <CondensedToolGroup key={item.id} group={item} onSendMessage={onSendMessage} />
240→                ) : item.message.userQuestion ? (
241→                  <UserQuestion key={item.message.id} message={item.message} onRespond={onRespondToUserQuestion} />
242→                ) : item.message.controlRequest ? (
243→                  <ControlRequest key={item.message.id} message={item.message} onRespond={onRespondToControl} />
244→                ) : (
245→                  <Message key={item.message.id} message={item.message} onSendMessage={onSendMessage} />
246→                )}
247→              </div>
248→            )}
249→            components={{
250→              Header: () => <div className="h-2" />,
251→              Footer: showContext ? () => (
252→                <div className="px-2 pb-2 md:px-4">
253→                  <div className="flex flex-col gap-0.5 items-start">
254→                    <ContextUsageCard rawMessages={rawMessages} activeModel={activeModel} />
255→                  </div>
256→                </div>
257→              ) : undefined,
258→              EmptyPlaceholder: () => (
259→                <div className="flex h-full flex-col items-center justify-center gap-4 text-muted-foreground">
260→                  <Terminal className="size-10 opacity-30" />
261→                  <div className="text-center">
262→                    <p className="text-sm font-medium text-foreground/80">No agent selected</p>
263→                    <p className="mt-1 text-xs">Type a prompt below to spawn a Claude agent</p>
264→                  </div>
265→                  <div className="mt-2 grid grid-cols-2 gap-3 text-[11px]">
266→                    <div className="flex items-start gap-2 rounded-lg border p-3">
267→                      <MessageSquare className="mt-0.5 size-3.5 shrink-0 text-primary" />
268→                      <div>
269→                        <p className="font-medium text-foreground/80">Chat</p>
270→                        <p className="mt-0.5">Send prompts and review tool calls in real time</p>
271→                      </div>
272→                    </div>
273→                    <div className="flex items-start gap-2 rounded-lg border p-3">
274→                      <ListTodo className="mt-0.5 size-3.5 shrink-0 text-primary" />
275→                      <div>
276→                        <p className="font-medium text-foreground/80">Tasks</p>
277→                        <p className="mt-0.5">Track work with a kanban board and delegate to agents</p>
278→                      </div>
279→                    </div>
280→                  </div>
281→                </div>
282→              ),
283→            }}
284→          />
285→        )}
286→        {!atBottom && displayItems.length > 0 && !showRaw && !loading && (
287→          <button
288→            onClick={() => virtuosoRef.current?.scrollToIndex({ index: displayItems.length - 1, behavior: "smooth" })}
289→            className="absolute bottom-3 right-3 flex items-center gap-1 rounded-full border bg-background/90 px-3 py-1.5 text-xs text-muted-foreground shadow-md backdrop-blur transition-colors hover:text-foreground"
290→          >
291→            <ArrowDown className="size-3" />
292→            Latest
293→          </button>
294→        )}
295→      </div>
296→
297→      {isArchived && messages.length > 0 ? (
298→        <div className="border-t px-4 py-2 text-center text-xs text-muted-foreground">
299→          This session has ended
300→        </div>
301→      ) : (
302→        <form
303→          onSubmit={handleSubmit}
304→          className="relative flex gap-2 border-t px-2 py-2 md:px-4 md:py-3"
305→        >
306→          {showSlashMenu && (
307→            <SlashCommandMenu
308→              query={slashQuery}
309→              highlightedIndex={slashHighlight}
310→              onSelect={handleCommandSelect}
311→              onHighlight={setSlashHighlight}
312→            />
313→          )}
314→          <input
315→            ref={inputRef}
316→            type="text"
317→            value={input}
318→            onChange={handleInputChange}
319→            onKeyDown={handleKeyDown}
320→            placeholder={isActive ? "Send a follow-up..." : "Enter a prompt to spawn agent..."}
321→            className="flex-1 rounded-md border bg-background px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-ring"
322→          />
323→          <Button type="submit" disabled={!connected || !input.trim()}>
324→            {isActive ? "Send" : "Spawn"}
325→          </Button>
326→        </form>
327→      )}
328→    </div>
329→  );
330→}
331→
332→/** Badge color per Claude NDJSON message type. */
333→const TYPE_COLORS: Record<string, string> = {
334→  system: "text-yellow-500",
335→  assistant: "text-blue-400",
336→  result: "text-green-500",
337→  control_request: "text-orange-400",
338→  keep_alive: "text-muted-foreground",
339→};
340→
341→function RawMessage({ message, index }: { message: ClaudeMessage; index: number }) {
342→  const [expanded, setExpanded] = useState(false);
343→  const subtype = (message as { subtype?: string }).subtype;
344→  const typeLabel = subtype ? `${message.type}/${subtype}` : message.type;
345→  const colorClass = TYPE_COLORS[message.type] ?? "text-muted-foreground";
346→
347→  return (
348→    <div className="font-mono text-[11px] leading-relaxed">
349→      <button
350→        onClick={() => setExpanded((v) => !v)}
351→        className="flex w-full items-center gap-2 rounded px-2 py-1 text-left hover:bg-muted/50 transition-colors"
352→      >
353→        <span className="text-muted-foreground w-6 shrink-0 text-right">{index}</span>
354→        <span className={colorClass}>{typeLabel}</span>
355→        <span className="text-muted-foreground">{expanded ? "▼" : "▶"}</span>
356→      </button>
357→      {expanded && (
358→        <pre className="ml-10 overflow-x-auto rounded bg-muted/30 p-2 text-[10px] text-muted-foreground whitespace-pre-wrap break-all">
359→          {JSON.stringify(message, null, 2)}
360→        </pre>
361→      )}
362→    </div>
363→  );
364→}
