  3→/**
  4→ * Dashboard route (`/dashboard`).
  5→ *
  6→ * Orchestrates the multi-agent WebSocket hook, sidebar, chat panel, and
  7→ * task panel. Clicking "+" or selecting "New Agent" sets `activeAgentId`
  8→ * to `null`, which shows the spawn input. On spawn, the server responds
  9→ * with `spawned` and the hook auto-selects the new agent.
 10→ *
 11→ * ## Loading states
 12→ *
 13→ * Two loading flags from the hook control the UI:
 14→ * - `initialLoadDone` — false until the first `agent_list` arrives from
 15→ *   the server. While false, the sidebar shows skeleton rows.
 16→ * - `historyLoading` — true when the active agent's message history has
 17→ *   not been fetched yet (lazy loading). The chat shows a "Loading
 18→ *   messages..." indicator until the server responds.
 19→ *
 20→ * Sidebar uses `!initialLoadDone`, chat uses `!initialLoadDone || historyLoading`.
 21→ */
 22→
 23→import { useEffect, useRef, useState } from "react";
 24→import { toast } from "sonner";
 25→import { useWebSocket } from "@/hooks/use-websocket";
 26→import {
 27→  initNotifications,
 28→  isNotificationsEnabled,
 29→  setNotificationsEnabled,
 30→  requestPermission,
 31→} from "@/lib/notifications";
 32→import { AgentSidebar } from "@/components/dashboard/agent-sidebar";
 33→import { Chat } from "@/components/dashboard/chat";
 34→import { TaskPanel, type TaskViewMode } from "@/components/dashboard/kanban-board";
 35→import { DiffsPanel } from "@/components/dashboard/diffs-panel";
 36→import { FolderBrowser } from "@/components/dashboard/folder-browser";
 37→import { SfxSettings } from "@/components/dashboard/sfx-settings";
 38→import { Toaster } from "@/components/ui/sonner";
 39→import { TooltipProvider } from "@/components/ui/tooltip";
 40→import { cn } from "@/lib/utils";
 41→
 42→export default function DashboardPage() {
 43→  const {
 44→    connected,
 45→    initialLoadDone,
 46→    historyLoading,
 47→    agents,
 48→    agentOrder,
 49→    activeAgentId,
 50→    setActiveAgentId,
 51→    activeStatus,
 52→    activeMessages,
 53→    activeRawMessages,
 54→    activeModel,
 55→    spawnAgent,
 56→    sendMessage,
 57→    respondToControl,
 58→    respondToUserQuestion,
 59→    killAgent,
 60→    deleteAgent,
 61→    renameAgent,
 62→    clearHistory,
 63→    pinAgent,
 64→    iceboxAgent,
 65→    moveAgent,
 66→    tasks,
 67→    createTask,
 68→    updateTask,
 69→    deleteTask,
 70→    delegateTask,
 71→    workspaces,
 72→    activeWorkspaceId,
 73→    setActiveWorkspaceId,
 74→    createWorkspace,
 75→    renameWorkspace,
 76→    deleteWorkspace,
 77→    browseDirectory,
 78→    directoryListing,
