 95→    initNotifications();
 96→    setNotificationsEnabledState(isNotificationsEnabled());
 97→  }, []);
 98→
 99→  const handleToggleNotifications = async () => {
100→    if (!notificationsEnabled) {
101→      // Enabling: request permission first if needed
102→      const granted = await requestPermission();
103→      if (!granted && typeof window !== "undefined" && "Notification" in window && Notification.permission === "denied") {
104→        toast.error("Notifications blocked — enable in browser settings");
