152→          agents={agents}
153→          agentOrder={agentOrder}
154→          activeAgentId={activeAgentId}
155→          loading={!initialLoadDone}
156→          onSelect={(id) => {
157→            setActiveAgentId(id);
158→            setSidebarOpen(false);
159→          }}
160→          onNewAgent={() => {
161→            setActiveAgentId(null);
162→            setSidebarOpen(false);
163→          }}
164→          onKill={killAgent}
165→          onDelete={deleteAgent}
166→          onRename={renameAgent}
167→          onClearHistory={clearHistory}
168→          onPin={pinAgent}
169→          onIcebox={iceboxAgent}
170→          onMoveAgent={moveAgent}
171→          workspaces={workspaces}
172→          activeWorkspaceId={activeWorkspaceId}
173→          onSelectWorkspace={setActiveWorkspaceId}
174→          onRenameWorkspace={renameWorkspace}
