222→
223→      {/* Task panel drawer */}
224→      {taskView !== "hidden" && (
225→        <div
226→          className={cn(
227→            "fixed inset-y-0 right-0 z-50 border-l bg-background flex flex-col min-w-0 md:relative md:z-auto",
228→            taskView === "board"
229→              ? "w-full max-w-none"
