  }));
}
```

---

## 8. **Multi-Turn Conversations**

**File:** `/Users/chiu.fyi/thos/hooks/use-websocket.ts` (lines 733-753)

After a `result` message, the agent stays `connected`. User can send follow-up messages:

```typescript
const sendMessage = useCallback(
  (content: string) => {
    if (!activeAgentId) return;

    // Optimistically add to local UI
    updateAgent(activeAgentId, (prev) => ({
      ...prev,
      messages: [...prev.messages, { id: nextId(), role: "user", content, timestamp: Date.now() }]
    }));

    // Send to server
    send({ type: "send_message", agentId: activeAgentId, content });
  },
  [send, activeAgentId, updateAgent]
);
```

Server handler (lines 681-720):
```typescript
case "send_message": {
  const agent = agents.get(msg.agentId);

  // Record in history
  agent.messageHistory.push({
    type: "relay",
    agentId: msg.agentId,
    message: { type: "user", message: { role: "user", content: msg.content } }
  });

  if (agent.claudeSocket?.readyState === WebSocket.OPEN) {
    // Send immediately if connected
    const userMsg = JSON.stringify({
      type: "user",
      message: { role: "user", content: msg.content },
      parent_tool_use_id: null,
      session_id: agent.sessionId ?? ""
    });
    agent.claudeSocket.send(userMsg + "\n");
    setAgentStatus(msg.agentId, "thinking");
  } else {
    // Queue if disconnected, flush on reconnect
    agent.pendingMessages.push(userMsg);
  }
}
```

---

## 9. **Task Delegation Flow**

**File:** `/Users/chiu.fyi/thos/server/ws.ts` (lines 852-863)

```typescript
case "delegate_task": {
  const task = tasks.get(msg.taskId);
  if (!task) break;

  // Build prompt from task
  const prompt = `Task: ${task.title}\n\n${task.description}`;

  // Spawn new agent with this prompt
  const agentId = spawnClaude(prompt, task.workspaceId);

  // Link task to agent
  task.agentId = agentId;
  task.status = "in-progress";
  task.updatedAt = Date.now();
  persistTasks();
  broadcastTaskList();
}
```

When the agent finishes (CLI disconnects after `result`):
```typescript
ws.on("close", () => {
  // ... 
  // Auto-complete linked task
  for (const task of tasks.values()) {
    if (task.agentId === agentId && task.status !== "done") {
      task.status = "done";
      task.updatedAt = Date.now();
      persistTasks();
      broadcastTaskList();
    }
  }
});
```

---

## 10. **Persistence & Recovery**

**Files:** 
- `/Users/chiu.fyi/thos/server/ws.ts` (lines 214-265, 294-296, 327-329)
- `/Users/chiu.fyi/thos/server/session-store.ts`

Agent state is persisted to `.thos/sessions/{agentId}.json` with:
- **Debounced saves (150ms)** for streaming messages (via `persistAgent()`)
- **Sync saves** for critical state changes like spawn/kill (via `persistAgentSync()`)

On server restart:
```typescript
function restoreAgents() {
  const persisted = store.loadAll();
  const aliveSessions = listAliveTmuxSessions();

  for (const p of persisted) {
    const agent = { /* restore state */ };

    if (agent.status !== "done" && agent.status !== "error") {
      const tmuxAlive = agent.tmuxSession ? aliveSessions.has(agent.tmuxSession) : false;
      if (tmuxAlive) {
        agent.status = "disconnected";  // Waiting for CLI to reconnect
      } else {
        agent.status = "done";          // Archive if tmux is gone
      }
    }
  }
}
```

**Critical insight:** tmux sessions are NOT killed on server shutdown, allowing CLI processes to reconnect and resume!

---

## 11. **Type Definitions**

**File:** `/Users/chiu.fyi/thos/lib/types.ts`

### Key Types:

```typescript
// Browser → Server
