551→  });
552→
553→  tmux.on("exit", (code) => {
554→    if (code !== 0) {
555→      console.error(`[tmux] new-session exited with code ${code}`);
556→      setAgentStatus(agentId, "error");
557→      recordAndSend(agentId, { type: "error", agentId, error: `tmux exited with code ${code}` });
558→      return;
559→    }
560→    console.log(`[tmux] session ${sessionName} created — attach with: tmux attach -t ${sessionName}`);
561→    agent.tmuxSession = sessionName;
562→    broadcastAgentList();
563→    persistAgentSync(agent);
